import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are the virtual assistant for 'Apalanchii Hospedaje y Restaurante' in Cabo de la Vela, La Guajira, Colombia.
Your goal is to help visitors with information about the hotel, the restaurant, local tours (Cueva del Diablo, Ojo de Agua, El Morro), and the Wayuu culture.
Always be polite, helpful, and provide a coastal, warm vibe. 
Use Google Search grounding to provide real-time information about weather in Cabo de la Vela or recent travel updates.
If you are asked about room prices or booking, suggest contacting them via WhatsApp at +57 312 630 6637.
`;

export const chatWithAssistant = async (message: string, lang: 'es' | 'en') => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `User language: ${lang}. User message: ${message}`,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "I'm sorry, I couldn't process that.";
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(chunk => chunk.web?.uri).filter(Boolean) as string[];

    return { text, sources: sources || [] };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { text: "Error connecting to the assistant. Please try again later.", sources: [] };
  }
};

import React from 'react';
import { Language } from '../types';

interface Props {
  current: Language;
  onToggle: (lang: Language) => void;
}

export const LanguageToggle: React.FC<Props> = ({ current, onToggle }) => {
  return (
    <div className="flex bg-slate-100 rounded-lg p-1">
      <button
        onClick={() => onToggle('es')}
        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${
          current === 'es' ? 'bg-white shadow-sm text-[#0b3b52]' : 'text-slate-400 hover:text-slate-600'
        }`}
      >
        ES
      </button>
      <button
        onClick={() => onToggle('en')}
        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${
          current === 'en' ? 'bg-white shadow-sm text-[#0b3b52]' : 'text-slate-400 hover:text-slate-600'
        }`}
      >
        EN
      </button>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { chatWithAssistant } from '../services/geminiService';
import { Language, TranslationStrings } from '../types';

interface Props {
  lang: Language;
  t: TranslationStrings;
}

export const AIAssistant: React.FC<Props> = ({ lang, t }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ text: string; sender: 'user' | 'bot'; sources?: string[] }[]>([]);
  const [input, setInput] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking]);

  const handleSend = async () => {
    if (!input.trim() || isThinking) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { text: userMsg, sender: 'user' }]);
    setIsThinking(true);

    const response = await chatWithAssistant(userMsg, lang);
    setMessages(prev => [...prev, { text: response.text, sender: 'bot', sources: response.sources }]);
    setIsThinking(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100] font-sans">
      {/* Trigger Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="w-14 h-14 bg-[#1f7a8c] text-white rounded-full shadow-lg hover:bg-[#0b3b52] flex items-center justify-center transition-all transform hover:scale-105"
      >
        {isOpen ? (
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
        ) : (
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
        )}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="absolute bottom-16 right-0 w-[350px] md:w-[400px] h-[500px] bg-white rounded-2xl shadow-2xl flex flex-col overflow-hidden border border-slate-100">
          {/* Header */}
          <div className="bg-[#0b3b52] p-4 text-white flex items-center gap-3">
            <div className="w-10 h-10 bg-[#1f7a8c] rounded-full flex items-center justify-center font-bold">A</div>
            <div>
              <h3 className="text-sm font-bold">Apalanchii Guide</h3>
              <p className="text-[10px] opacity-70">Powered by Gemini AI</p>
            </div>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
            {messages.length === 0 && (
              <div className="text-center py-10 px-6">
                <p className="text-slate-500 text-sm leading-relaxed">{t.assistant.greeting}</p>
              </div>
            )}
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${
                  msg.sender === 'user' 
                    ? 'bg-[#1f7a8c] text-white rounded-tr-none' 
                    : 'bg-white text-slate-800 shadow-sm border border-slate-100 rounded-tl-none'
                }`}>
                  {msg.text}
                  {msg.sources && msg.sources.length > 0 && (
                    <div className="mt-2 pt-2 border-top border-slate-100 space-y-1">
                      <p className="text-[10px] uppercase font-bold text-slate-400">Sources:</p>
                      {msg.sources.map((s, i) => (
                        <a key={i} href={s} target="_blank" rel="noopener noreferrer" className="block text-[10px] text-blue-500 truncate hover:underline">
                          {s}
                        </a>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            ))}
            {isThinking && (
              <div className="flex justify-start">
                <div className="bg-white p-3 rounded-2xl shadow-sm border border-slate-100 rounded-tl-none">
                  <span className="flex gap-1">
                    <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce"></span>
                    <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce delay-100"></span>
                    <span className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce delay-200"></span>
                  </span>
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-4 bg-white border-t border-slate-100 flex gap-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder={t.assistant.placeholder}
              className="flex-1 text-sm bg-slate-100 border-none rounded-xl px-4 py-2 focus:ring-2 focus:ring-[#1f7a8c] focus:bg-white transition-all outline-none"
            />
            <button
              onClick={handleSend}
              className="w-10 h-10 bg-[#0b3b52] text-white rounded-xl flex items-center justify-center hover:bg-[#1f7a8c] transition-all"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

