import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.tsx';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <App />
);

import React, { useState, useEffect } from 'react';
import { translations } from './translations.ts';
import { Language } from './types.ts';
import { LanguageToggle } from './components/LanguageToggle.tsx';
import { AIAssistant } from './components/AIAssistant.tsx';

type View = 'inicio' | 'hospedaje' | 'restaurante' | 'experiencias';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('es');
  const [currentView, setCurrentView] = useState<View>('inicio');
  const [scrolled, setScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const t = translations[lang];

  useEffect(() => {
    // Quitar splash screen cuando React está listo y el componente montado
    document.body.classList.add('loaded');

    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'instant' });
    setIsMenuOpen(false);
  }, [currentView]);

  const navItems: { id: View; label: string }[] = [
    { id: 'inicio', label: t.nav.home },
    { id: 'hospedaje', label: t.nav.lodging },
    { id: 'restaurante', label: t.nav.restaurant },
    { id: 'experiencias', label: t.nav.experiences }
  ];

  const SubpageHero = ({ title, subtitle, bgImage, category }: { title: string, subtitle: string, bgImage: string, category: string }) => (
    <section className="h-[70vh] relative flex items-center justify-center overflow-hidden bg-[#0b3b52]">
      <div 
        className="absolute inset-0 bg-cover bg-center scale-105 animate-slow-zoom"
        style={{ backgroundImage: `url('${bgImage}')` }}
      />
