const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('es');
  const [currentView, setCurrentView] = useState<View>('inicio');
  const [scrolled, setScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const t = useMemo(() => translations[lang], [lang]);

  useEffect(() => {
    // Splash screen optimizado
    const timer = setTimeout(() => {
      document.body.classList.add('loaded');
    }, 100);

    // Scroll listener ligero
    let ticking = false;
    const handleScroll = () => {
      if (!ticking) {
        window.requestAnimationFrame(() => {
          setScrolled(window.scrollY > 40);
          ticking = false;
        });
        ticking = true;
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearTimeout(timer);
    };
  }, []);

  const changeView = (v: View) => {
    if (v === currentView) return;
    setCurrentView(v);
    setIsMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'auto' }); // Cambiado a 'auto' para velocidad pura
  };

  const navItems: { id: View; label: string }[] = useMemo(() => [
    { id: 'inicio', label: t.nav.home },
    { id: 'hospedaje', label: t.nav.lodging },
    { id: 'restaurante', label: t.nav.restaurant },
    { id: 'experiencias', label: t.nav.experiences }
  ], [t]);

  return (
    <div className="min-h-screen bg-white flex flex-col font-sans overflow-x-hidden">
      <header className={`fixed top-0 left-0 right-0 z-50 glass-header ${
        scrolled || currentView !== 'inicio' ? 'bg-white/90 shadow-md py-2.5' : 'bg-transparent py-5'
      }`}>
        <div className="max-w-7xl mx-auto px-6 flex items-center justify-between">
          <button onClick={() => changeView('inicio')} className="active:scale-95 transition-transform">
            <img 
              src="https://static.wixstatic.com/media/be13c5_abf5374c2bc448dda014a47f245f7cbc~mv2.png" 
              alt="Apalanchii" 
              className={`h-7 md:h-8 w-auto transition-all ${(scrolled || currentView !== 'inicio') ? '' : 'brightness-0 invert'}`} 
            />
          </button>

          <nav className="hidden md:flex items-center gap-8">
            {navItems.map(s => (
              <button 
                key={s.id} 
                onClick={() => changeView(s.id)}
                className={`text-[10px] font-black uppercase tracking-[0.2em] transition-colors relative py-1 ${
                  (scrolled || currentView !== 'inicio') ? 'text-[#0b3b52]' : 'text-white'
                } hover:text-[#1f7a8c] ${currentView === s.id ? 'after:content-[""] after:absolute after:-bottom-1 after:left-0 after:w-full after:h-0.5 after:bg-[#1f7a8c]' : ''}`}
              >
                {s.label}
              </button>
            ))}
          </nav>

          <div className="flex items-center gap-4">
            <LanguageToggle current={lang} onToggle={setLang} />
            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className={`md:hidden p-2 transition-colors ${
                (scrolled || currentView !== 'inicio') ? 'text-[#0b3b52]' : 'text-white'
              }`}
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
            </button>
          </div>
        </div>

        {isMenuOpen && (
          <div className="md:hidden absolute top-full left-0 right-0 bg-white shadow-xl animate-reveal p-4 space-y-1">
            {navItems.map(s => (
              <button 
                key={s.id} 
                onClick={() => changeView(s.id)}
                className={`block w-full text-left px-5 py-3 rounded-xl font-black uppercase tracking-widest text-[10px] ${
                  currentView === s.id ? 'bg-[#0b3b52] text-white' : 'text-[#0b3b52]'
                }`}
              >
                {s.label}
              </button>
            ))}
          </div>
        )}
      </header>

      <main className="flex-1">
        {currentView === 'inicio' && <HomeView t={t} setView={changeView} />}
        {currentView === 'hospedaje' && <LodgingView t={t} />}
        {currentView === 'restaurante' && <RestaurantView t={t} />}
        {currentView === 'experiencias' && <ExperiencesView t={t} />}
      </main>

      <footer className="relative text-white">
        <div className="w-full leading-[0] overflow-hidden">
          <svg viewBox="0 0 1200 100" preserveAspectRatio="none" className="w-full h-12 md:h-16">
            <path d="M0,0 C300,100 900,0 1200,80 L1200,100 L0,100 Z" fill="#1f7a8c"></path>
          </svg>
        </div>
        <div className="bg-[#1f7a8c] bg-gradient-to-br from-[#0b3b52] to-[#1f7a8c] px-6 py-10 md:py-12">
          <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
            <img src="https://static.wixstatic.com/media/be13c5_abf5374c2bc448dda014a47f245f7cbc~mv2.png" alt="Apalanchii" className="h-7 brightness-0 invert" />
            <p className="text-white/60 text-[10px] uppercase tracking-widest font-medium">
              © 2025 Apalanchii – {t.footer.rights}
            </p>
            <div className="flex gap-4">
               <a href="https://wa.me/573126306637" className="text-white/80 hover:text-white transition-colors text-xs font-bold uppercase tracking-widest">+57 312 630 6637</a>
            </div>
          </div>
        </div>
      </footer>

      <AIAssistant lang={lang} t={t} />
    </div>
  );
};

export default App;

