const ExperiencesView = memo(({ t }: { t: TranslationStrings }) => {
  const [reviews, setReviews] = useState<GoogleReview[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Lógica para obtener reseñas reales de Google Maps (Google Places API)
    const fetchReviews = () => {
      // Use type casting to access 'google' on the window object and a local variable to fix TS errors for the 'google' namespace.
      const g = (window as any).google;
      if (!g || !g.maps) {
        // Fallback si la API no carga
        setReviews([
          { author_name: "Andrés Rodríguez", text: "Excelente atención y la comida es deliciosa. La vista al mar desde la enramada es insuperable. Volveré sin duda.", rating: 5, relative_time_description: "Hace 1 mes" },
          { author_name: "Lucía Méndez", text: "Un lugar mágico. La tranquilidad del Cabo se siente en cada rincón de Apalanchii. Las habitaciones son frescas y cómodas.", rating: 5, relative_time_description: "Hace 2 meses" },
          { author_name: "Carlos V.", text: "La mejor experiencia wayuu. La calidez del personal y la cercanía a la playa hacen que te sientas en casa.", rating: 4, relative_time_description: "Hace 3 semanas" }
        ]);
        setLoading(false);
        return;
      }

      const service = new g.maps.places.PlacesService(document.createElement('div'));
      const request = {
        query: 'Apalanchii Hospedaje y Restaurante, Cabo de la Vela, La Guajira',
        fields: ['place_id', 'reviews', 'rating', 'user_ratings_total']
      };

      service.textSearch(request, (results: any, status: any) => {
        if (status === g.maps.places.PlacesServiceStatus.OK && results && results[0]) {
          service.getDetails({ 
            placeId: results[0].place_id!,
            fields: ['reviews']
          }, (place: any, detailStatus: any) => {
            if (detailStatus === g.maps.places.PlacesServiceStatus.OK && place?.reviews) {
              const sorted = [...place.reviews].sort((a: any, b: any) => (b.rating || 0) - (a.rating || 0)).slice(0, 3);
              setReviews(sorted as GoogleReview[]);
            }
            setLoading(false);
          });
        } else {
          setLoading(false);
        }
      });
    };

    const timer = setTimeout(fetchReviews, 1000); // Dar tiempo a que cargue el script
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="view-transition">
      <SubpageHero 
        title={t.experiences.title} 
        subtitle={t.experiences.lead} 
        bgImage="https://static.wixstatic.com/media/be13c5_fa5793f6013847e1b92e0fcd39ca7bb5~mv2.png"
      />

      {/* Galería de Imágenes */}
      <section className="py-16 px-6 bg-white overflow-hidden">
        <div className="max-w-7xl mx-auto">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-24">
            {[
              { img: 'https://static.wixstatic.com/media/be13c5_fa5793f6013847e1b92e0fcd39ca7bb5~mv2.png', label: 'Punta Gallina' },
              { img: 'https://static.wixstatic.com/media/be13c5_f3a9de846dee4298bd09a2134f8c7a3e~mv2.jpg', label: 'Pilón de Azúcar' },
              { img: 'https://static.wixstatic.com/media/be13c5_be1ef171c3cf4733adc637f6a1e0dc03~mv2.png', label: 'Cueva del Diablo' },
              { img: 'https://static.wixstatic.com/media/be13c5_5ca5c936fc874ea1ba50c59d5ceaf470~mv2.png', label: 'Ojo de Agua' }
            ].map((item, i) => (
              <div key={i} className={`group relative h-[380px] rounded-[2rem] overflow-hidden bg-slate-100 shadow-md animate-reveal stagger-${i+1}`}>
                <img loading="lazy" decoding="async" src={item.img} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" alt={item.label} />
                <div className="absolute inset-0 bg-gradient-to-t from-[#0b3b52]/80 via-transparent to-transparent flex items-end p-6 text-white">
                  <p className="font-black text-xl leading-tight">{item.label}</p>
                </div>
              </div>
            ))}
          </div>

          {/* Restauración de la Sección de Reseñas de Google Maps */}
          <div className="animate-reveal">
            <div className="flex flex-col items-center text-center mb-16 border-b border-slate-100 pb-10 gap-2">
              <span className="text-[10px] font-black text-[#1f7a8c] uppercase tracking-[0.4em] mb-3 block">Nuestros Huéspedes</span>
              <h2 className="text-3xl md:text-4xl font-black text-[#0b3b52] uppercase tracking-tight">{t.experiences.reviewsTitle}</h2>
              <div className="mt-4 flex items-center gap-2">
                <div className="flex gap-1">
                  {[1,2,3,4,5].map(s => <svg key={s} className="w-4 h-4 fill-[#f5a623]" viewBox="0 0 24 24"><path d="M12 17.27 18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/></svg>)}
                </div>
                <span className="text-[10px] font-bold text-slate-400 tracking-widest uppercase">Reseñas de Google</span>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
              {loading ? (
                [1, 2, 3].map(i => (
                  <div key={i} className="h-64 bg-slate-50 rounded-[2rem] animate-pulse"></div>
                ))
              ) : reviews.length > 0 ? (
                reviews.map((rev, idx) => (
                  <article key={idx} className="p-10 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all group">
                    <div className="flex items-center gap-5 mb-6">
                      {rev.profile_photo_url ? (
