                    <div className="flex items-center justify-between pt-4 border-t border-slate-50">
                      <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{rev.relative_time_description}</span>
                      <img src="https://upload.wikimedia.org/wikipedia/commons/c/c1/Google_Maps_icon_%282020%29.svg" className="w-4 opacity-50" alt="Google" />
