import React, { useState, useRef, useEffect, useMemo } from 'react';
import { createChatSession } from '../services/geminiService.ts';
import { Language, TranslationStrings } from '../types.ts';
import { GenerateContentResponse } from "@google/genai";

interface Message {
  text: string;
  sender: 'user' | 'bot';
  sources?: string[];
  isStreaming?: boolean;
}

interface Props {
  lang: Language;
  t: TranslationStrings;
}

export const AIAssistant: React.FC<Props> = ({ lang, t }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [showPrompt, setShowPrompt] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isThinking, setIsThinking] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const chatInstance = useMemo(() => createChatSession(lang), [lang]);

  // Mostrar invitación después de 5 segundos
  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isOpen) setShowPrompt(true);
    }, 5000);
    return () => clearTimeout(timer);
  }, [isOpen]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking]);

  const handleSend = async () => {
    if (!input.trim() || isThinking) return;

    const userMsg = input.trim();
    setInput('');
    setShowPrompt(false);
    setMessages(prev => [...prev, { text: userMsg, sender: 'user' }]);
    setIsThinking(true);

    try {
      const responseStream = await chatInstance.sendMessageStream({ message: userMsg });

      // Añadimos el mensaje del bot vacío para empezar el streaming
      setMessages(prev => [...prev, { text: '', sender: 'bot', isStreaming: true }]);

      let fullText = '';
      let sources: string[] = [];

      for await (const chunk of responseStream) {
        const c = chunk as GenerateContentResponse;
        const newPart = c.text || "";
        fullText += newPart;

        // Intentar extraer fuentes si el chunk las trae (grounding metadata)
        const chunkSources = c.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(ch => ch.web?.uri).filter(Boolean) as string[];
        if (chunkSources?.length) sources = Array.from(new Set([...sources, ...chunkSources]));

        setMessages(prev => {
          const updated = [...prev];
          const lastIndex = updated.length - 1;
          if (updated[lastIndex].sender === 'bot') {
            updated[lastIndex] = { ...updated[lastIndex], text: fullText, sources };
          }
          return updated;
        });
      }

      // Marcar el final del streaming
      setMessages(prev => {
        const updated = [...prev];
        const lastIndex = updated.length - 1;
        if (updated[lastIndex].sender === 'bot') {
          updated[lastIndex].isStreaming = false;
        }
        return updated;
      });

    } catch (error) {
      console.error("Chat Error:", error);
      setMessages(prev => [...prev, { 
        text: lang === 'es' ? "Lo siento, tuve un problema de conexión. ¿Podrías intentar de nuevo?" : "Sorry, I had a connection issue. Could you try again?", 
        sender: 'bot' 
      }]);
    } finally {
      setIsThinking(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100] font-sans pointer-events-none">
      {/* Globo de invitación proactiva (Posicionado hacia arriba) */}
      {showPrompt && !isOpen && (
        <div className="absolute bottom-[72px] right-0 mb-3 w-48 bg-white p-4 rounded-2xl shadow-2xl border border-slate-100 animate-reveal pointer-events-auto origin-bottom-right">
          <p className="text-[11px] font-medium text-slate-700 leading-tight">
            {lang === 'es' ? '¡Hola! ¿Deseas saber el clima o los platos del día?' : 'Hi! Want to know the weather or today\'s menu?'}
          </p>
          <div className="absolute bottom-[-6px] right-6 w-3 h-3 bg-white border-r border-b border-slate-100 rotate-45"></div>
        </div>
      )}

      {/* Botón Flotante */}
      <button
        onClick={() => { setIsOpen(!isOpen); setShowPrompt(false); }}
        className="ml-auto w-14 h-14 bg-[#0b3b52] text-white rounded-full shadow-2xl hover:bg-[#1f7a8c] flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 pointer-events-auto group"
        aria-label="Asistente Virtual"
      >
        {isOpen ? (
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
        ) : (
          <div className="relative">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
            {!isOpen && <span className="absolute -top-1 -right-1 w-3 h-3 bg-[#CBA76B] rounded-full border-2 border-[#0b3b52] animate-pulse"></span>}
          </div>
        )}
      </button>

      {/* Ventana de Chat (Posicionada hacia arriba) */}
      {isOpen && (
        <div className="absolute bottom-[72px] right-0 w-[320px] md:w-[400px] h-[520px] bg-white rounded-[2rem] shadow-2xl flex flex-col overflow-hidden border border-slate-100 animate-reveal pointer-events-auto mb-2 origin-bottom-right">
          {/* Header */}
          <div className="bg-[#0b3b52] p-5 text-white flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 bg-white/10 rounded-xl flex items-center justify-center font-black text-xs text-[#CBA76B] shadow-inner">A</div>
              <div>
                <h3 className="text-[10px] font-black uppercase tracking-[0.2em]">{t.nav.home} Assistant</h3>
                <div className="flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse"></span>
                  <p className="text-[9px] font-bold text-white/50 uppercase tracking-widest">{lang === 'es' ? 'En línea' : 'Online'}</p>
                </div>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="opacity-40 hover:opacity-100 transition-opacity">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>

          {/* Cuerpo del Chat */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-5 bg-slate-50/50">
            {messages.length === 0 && (
              <div className="text-center py-12 px-6">
                <div className="w-12 h-12 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <svg className="w-6 h-6 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                </div>
                <p className="text-slate-400 text-xs leading-relaxed italic">{t.assistant.greeting}</p>
              </div>
            )}

            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-2xl text-[13px] leading-relaxed transition-all ${
                  msg.sender === 'user' 
                    ? 'bg-[#0b3b52] text-white rounded-tr-none shadow-lg shadow-[#0b3b52]/10' 
                    : 'bg-white text-slate-700 shadow-sm border border-slate-100 rounded-tl-none font-medium'
                }`}>
                  {msg.text || (msg.isStreaming && <span className="inline-block w-1.5 h-4 bg-[#1f7a8c] animate-pulse align-middle"></span>)}

                  {msg.sources && msg.sources.length > 0 && (
                    <div className="mt-3 pt-3 border-t border-slate-50">
                      <p className="text-[8px] font-black text-slate-300 mb-2 uppercase tracking-widest">Fuentes verificadas:</p>
                      <div className="flex flex-wrap gap-2">
                        {msg.sources.map((src, i) => (
                          <a key={i} href={src} target="_blank" rel="noopener noreferrer" className="px-2 py-1 bg-slate-50 rounded-md text-[9px] text-[#1f7a8c] font-bold hover:bg-[#1f7a8c] hover:text-white transition-all truncate max-w-[120px]">
                            {new URL(src).hostname}
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            ))}

            {isThinking && messages[messages.length-1]?.sender !== 'bot' && (
              <div className="flex justify-start">
                <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 rounded-tl-none">
                  <div className="flex gap-1.5">
                    <div className="w-1.5 h-1.5 bg-[#CBA76B] rounded-full animate-bounce"></div>
                    <div className="w-1.5 h-1.5 bg-[#CBA76B] rounded-full animate-bounce delay-100"></div>
                    <div className="w-1.5 h-1.5 bg-[#CBA76B] rounded-full animate-bounce delay-200"></div>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-4 bg-white border-t border-slate-100">
            <div className="flex gap-2 items-center bg-slate-50 rounded-2xl px-4 py-1.5 focus-within:ring-2 focus-within:ring-[#1f7a8c]/20 transition-all">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={t.assistant.placeholder}
                className="flex-1 text-[13px] bg-transparent border-none py-2.5 outline-none text-slate-700 placeholder:text-slate-400 font-medium"
              />
              <button
                onClick={handleSend}
                disabled={isThinking || !input.trim()}
                className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all ${
                  input.trim() ? 'bg-[#1f7a8c] text-white shadow-lg shadow-[#1f7a8c]/20' : 'bg-slate-200 text-slate-400'
                }`}
              >
                <svg className="w-4 h-4 transform rotate-45" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
              </button>
            </div>
            <p className="text-[8px] text-center text-slate-300 font-bold uppercase tracking-widest mt-3">IA impulsada por Gemini</p>
          </div>
        </div>
      )}
    </div>
  );
};

