                      )}
                    </div>

                    <div className="flex gap-0.5 mb-4 text-[#f5a623]">
                      {Array.from({ length: 5 }).map((_, i) => (
                        <svg key={i} className={`w-3 h-3 ${i < Math.round(rev.rating) ? 'fill-current' : 'fill-slate-200'}`} viewBox="0 0 24 24"><path d="M12 17.27 18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/></svg>
                      ))}
                    </div>

                    <blockquote className="text-slate-600 text-[13px] leading-relaxed mb-6 font-medium italic">
