              alt="Logo" 
              className={`absolute inset-0 h-full w-full object-contain transition-opacity duration-300 ${isTransparent ? 'opacity-0' : 'opacity-100'}`} 
            />
          </button>

          <nav className="hidden md:flex items-center gap-10">
            {navItems.map(s => (
              <button 
                key={s.id} 
                onClick={() => changeView(s.id)}
