                  isTransparent ? 'text-white hover:text-white/70' : 'text-[#0b3b52] hover:text-[#1f7a8c]'
                } ${currentView === s.id && !isTransparent ? 'border-b-2 border-[#1f7a8c]' : ''}`}
              >
                {s.label}
              </button>
            ))}
          </nav>

          <div className="flex items-center gap-4">
            <LanguageToggle current={lang} onToggle={setLang} dark={isTransparent} />
            <button onClick={() => setIsMenuOpen(!isMenuOpen)} className={`md:hidden ${isTransparent ? 'text-white' : 'text-[#0b3b52]'}`}>
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
            </button>
          </div>
        </div>

        {isMenuOpen && (
          <div className="md:hidden absolute top-full left-0 right-0 bg-white shadow-xl p-4 flex flex-col gap-4">
