      </main>

      <footer className="bg-[#0b3b52] text-white py-20 px-6">
        <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-12">
          <div className="flex flex-col items-center md:items-start gap-6">
            <img src="https://static.wixstatic.com/media/be13c5_abf5374c2bc448dda014a47f245f7cbc~mv2.png" className="h-10 w-auto brightness-0 invert" alt="Logo" />
            <p className="text-[10px] opacity-50 uppercase tracking-widest">{t.footer.address}</p>
          </div>
          <div className="text-center md:text-left">
            <h4 className="text-[10px] font-black uppercase tracking-[0.3em] mb-6 opacity-30">{t.footer.contact}</h4>
            <p className="text-sm font-bold">+57 312 630 6637</p>
            <p className="text-sm opacity-70">apalanchii@hotmail.com</p>
          </div>
          <div className="flex justify-center md:justify-end gap-4">
            <a href="#" className="w-10 h-10 rounded-full border border-white/10 flex items-center justify-center hover:bg-white/10">FB</a>
            <a href="#" className="w-10 h-10 rounded-full border border-white/10 flex items-center justify-center hover:bg-white/10">IG</a>
