              { img: 'https://static.wixstatic.com/media/be13c5_f3a9de846dee4298bd09a2134f8c7a3e~mv2.jpg', label: 'Pilón de Azúcar' },
              { img: 'https://static.wixstatic.com/media/be13c5_be1ef171c3cf4733adc637f6a1e0dc03~mv2.png', label: 'Cueva del Diablo' },
              { img: 'https://static.wixstatic.com/media/be13c5_5ca5c936fc874ea1ba50c59d5ceaf470~mv2.png', label: 'Ojo de Agua' }
            ].map((item, i) => (
              <div key={i} className="group relative h-[420px] rounded-3xl overflow-hidden bg-slate-50 animate-reveal stagger-1">
                <img src={item.img} className="w-full h-full object-cover grayscale-[30%] group-hover:grayscale-0 transition-all duration-1000 group-hover:scale-105" alt={item.label} />
                <div className="absolute bottom-0 left-0 right-0 p-8 bg-gradient-to-t from-black/60 to-transparent">
                  <p className="text-white font-bold text-lg">{item.label}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="text-center mb-20 animate-reveal">
            <h2 className="text-2xl font-black text-[#0b3b52] uppercase tracking-tighter mb-2">{t.experiences.reviewsTitle}</h2>
            <div className="w-10 h-0.5 bg-[#CBA76B] mx-auto"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 max-w-6xl mx-auto">
