const ExperiencesView = memo(({ t }: { t: TranslationStrings }) => {
  const [reviews, setReviews] = useState<GoogleReview[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchReviews = () => {
      const g = (window as any).google;
      if (!g || !g.maps) {
        setReviews([
          { author_name: "Andrés R.", text: "Excelente atención y la comida es deliciosa. La vista al mar es insuperable.", rating: 5, relative_time_description: "Hace 1 mes" },
          { author_name: "Lucía M.", text: "Un lugar mágico. La tranquilidad del Cabo se siente en cada rincón.", rating: 5, relative_time_description: "Hace 2 meses" },
          { author_name: "Carlos V.", text: "La mejor experiencia wayuu. La calidez del personal es única.", rating: 5, relative_time_description: "Hace 3 semanas" }
        ]);
        setLoading(false);
        return;
      }
      const service = new g.maps.places.PlacesService(document.createElement('div'));
      service.textSearch({ query: 'Apalanchii Cabo de la Vela' }, (results: any, status: any) => {
        if (status === g.maps.places.PlacesServiceStatus.OK && results[0]) {
          service.getDetails({ placeId: results[0].place_id, fields: ['reviews'] }, (place: any) => {
            if (place?.reviews) setReviews(place.reviews.slice(0, 3));
            setLoading(false);
          });
        } else setLoading(false);
      });
    };
    const timer = setTimeout(fetchReviews, 1000);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="view-transition">
      <SubpageHero 
        title={t.experiences.title} 
