const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('es');
  const [currentView, setCurrentView] = useState<View>('inicio');
  const [scrolled, setScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const t = useMemo(() => translations[lang], [lang]);

  useEffect(() => {
    document.body.classList.add('loaded');

    const handleScroll = () => {
      // Usamos el scrollY actual de forma directa para evitar dependencias circulares
      const isScrolled = window.scrollY > 40;
      setScrolled(s => {
        if (s !== isScrolled) return isScrolled;
        return s;
      });
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []); // Dependencias vacías para montar el listener una sola vez

  const isTransparent = !scrolled && currentView === 'inicio';

  const changeView = (v: View) => {
    setCurrentView(v);
    setIsMenuOpen(false);
    // Scroll inmediato sin animaciones pesadas para evitar flickering visual
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  return (
    <div className="min-h-screen bg-white flex flex-col font-sans overflow-x-hidden">
      {/* Header optimizado con aceleración por hardware */}
