const ExperiencesView = memo(({ t }: { t: TranslationStrings }) => {
  const [reviews, setReviews] = useState<GoogleReview[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchReviews = () => {
      const g = (window as any).google;
      if (!g || !g.maps) {
        setReviews([
          { author_name: "Andrés R.", text: "Excelente atención y la comida es deliciosa. La vista al mar es insuperable.", rating: 5, relative_time_description: "Hace 1 mes" },
          { author_name: "Lucía M.", text: "Un lugar mágico. La tranquilidad del Cabo se siente en cada rincón.", rating: 5, relative_time_description: "Hace 2 meses" },
          { author_name: "Carlos V.", text: "La mejor experiencia wayuu. La calidez del personal es única.", rating: 5, relative_time_description: "Hace 3 semanas" }
        ]);
        setLoading(false);
        return;
      }
      const service = new g.maps.places.PlacesService(document.createElement('div'));
      service.textSearch({ query: 'Apalanchii Cabo de la Vela' }, (results: any, status: any) => {
        if (status === g.maps.places.PlacesServiceStatus.OK && results[0]) {
          service.getDetails({ placeId: results[0].place_id, fields: ['reviews'] }, (place: any) => {
            if (place?.reviews) setReviews(place.reviews.slice(0, 3));
            setLoading(false);
          });
        } else setLoading(false);
      });
    };
    const timer = setTimeout(fetchReviews, 1200);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="view-transition">
      <SubpageHero 
        title={t.experiences.title} 
        subtitle={t.experiences.lead} 
        bgImage="https://static.wixstatic.com/media/be13c5_fa5793f6013847e1b92e0fcd39ca7bb5~mv2.png"
      />
      <section className="py-24 px-6 bg-white overflow-hidden">
        <div className="max-w-7xl mx-auto">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-32">
            {[
              { img: 'https://static.wixstatic.com/media/be13c5_fa5793f6013847e1b92e0fcd39ca7bb5~mv2.png', label: 'Punta Gallina' },
              { img: 'https://static.wixstatic.com/media/be13c5_f3a9de846dee4298bd09a2134f8c7a3e~mv2.jpg', label: 'Pilón de Azúcar' },
              { img: 'https://static.wixstatic.com/media/be13c5_be1ef171c3cf4733adc637f6a1e0dc03~mv2.png', label: 'Cueva del Diablo' },
              { img: 'https://static.wixstatic.com/media/be13c5_5ca5c936fc874ea1ba50c59d5ceaf470~mv2.png', label: 'Ojo de Agua' }
            ].map((item, i) => (
              <div key={i} className="group relative h-[450px] rounded-[2rem] overflow-hidden bg-slate-50 animate-reveal stagger-1">
                <img src={item.img} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-1000 group-hover:scale-110" alt={item.label} />
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-60 group-hover:opacity-100 transition-opacity"></div>
                <div className="absolute bottom-0 left-0 right-0 p-10 transform translate-y-4 group-hover:translate-y-0 transition-transform">
                  <p className="text-white font-black text-xl uppercase tracking-tighter italic">{item.label}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="text-center mb-20 animate-reveal">
            <h2 className="text-3xl font-black text-[#0b3b52] uppercase tracking-tighter mb-4">{t.experiences.reviewsTitle}</h2>
            <div className="w-16 h-1 bg-[#CBA76B] mx-auto rounded-full"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 max-w-6xl mx-auto">
            {loading ? [1,2,3].map(i => <div key={i} className="h-48 bg-slate-50 animate-pulse rounded-[2.5rem]"></div>) : 
              reviews.map((rev, idx) => (
                <div key={idx} className="bg-white p-10 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col items-center text-center group hover:shadow-xl transition-all">
                  <div className="w-14 h-14 rounded-2xl bg-slate-50 mb-6 flex items-center justify-center font-black text-[#0b3b52] text-xl group-hover:bg-[#1f7a8c] group-hover:text-white transition-colors">
                    {rev.author_name[0]}
                  </div>
                  <div className="flex gap-1.5 mb-6 text-[#f5a623]">
                    {Array.from({length: 5}).map((_, i) => <svg key={i} className="w-4 h-4 fill-current" viewBox="0 0 24 24"><path d="M12 17.27 18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.19 12 17.27z"/></svg>)}
                  </div>
                  <p className="text-slate-500 text-sm italic mb-8 leading-relaxed font-medium">"{rev.text.substring(0, 140)}..."</p>
                  <h4 className="text-[11px] font-black uppercase text-[#0b3b52] tracking-[0.3em]">{rev.author_name}</h4>
                </div>
              ))
            }
          </div>
        </div>
      </section>
    </div>
  );
});

