interface Props {
  t: TranslationStrings;
}

const setCookie = (name: string, value: string, days: number) => {
  let expires = "";
  if (days) {
    const date = new Date();
    date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
    expires = "; expires=" + date.toUTCString();
  }
  document.cookie = name + "=" + (value || "")  + expires + "; path=/";
};

const getCookie = (name: string): string | null => {
  const nameEQ = name + "=";
  const ca = document.cookie.split(';');
  for(let i=0; i < ca.length; i++) {
    let c = ca[i];
    while (c.charAt(0) === ' ') c = c.substring(1, c.length);
    if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length, c.length);
  }
  return null;
};

export const CookieConsent: React.FC<Props> = ({ t }) => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const consent = getCookie('cookie_consent');
    if (!consent) {
      setIsVisible(true);
    }
  }, []);

  const handleConsent = (consent: 'accepted' | 'rejected') => {
    setCookie('cookie_consent', consent, 365);
    setIsVisible(false);
  };

  return (
    <div 
      className={`fixed bottom-5 left-5 max-w-sm p-5 z-[200] rounded-2xl shadow-2xl transition-all duration-500 ease-in-out transform ${
        isVisible ? 'translate-y-0 opacity-100' : 'translate-y-12 opacity-0 pointer-events-none'
      }`}
      style={{
        backdropFilter: 'blur(16px) saturate(180%)',
        WebkitBackdropFilter: 'blur(16px) saturate(180%)',
        backgroundColor: 'rgba(255, 255, 255, 0.75)',
        border: '1px solid rgba(200, 200, 200, 0.2)'
      }}
    >
      <div className="flex items-start gap-4">
        <div className="flex-shrink-0 w-8 h-8 rounded-full bg-[#f7f0e3] flex items-center justify-center mt-1">
          <span className="text-sm">🍪</span>
        </div>
        <div>
          <h4 className="text-[13px] font-black text-[#0b3b52] mb-1">{t.cookie.title}</h4>
          <p className="text-[11px] text-slate-600 leading-relaxed">{t.cookie.message}</p>
          <div className="mt-4 flex gap-3">
            <button
              onClick={() => handleConsent('accepted')}
              className="px-4 py-1.5 bg-[#1f7a8c] text-white text-[10px] font-bold rounded-lg hover:bg-[#0b3b52] transition-colors"
            >
              {t.cookie.accept}
            </button>
            <button
              onClick={() => handleConsent('rejected')}
              className="px-4 py-1.5 text-slate-500 text-[10px] font-bold rounded-lg hover:bg-slate-100 transition-colors"
            >
              {t.cookie.reject}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

