const ExperiencesView = memo(({ t }: { t: TranslationStrings }) => {
  const [reviews, setReviews] = useState<GoogleReview[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchReviews = () => {
      const g = (window as any).google;
      if (!g || !g.maps) {
        setReviews([
          { author_name: "Andrés Rodríguez", text: "Excelente atención y la comida es deliciosa. La vista al mar desde la enramada es insuperable.", rating: 5, relative_time_description: "Hace 1 mes" },
          { author_name: "Lucía Méndez", text: "Un lugar mágico. La tranquilidad del Cabo se siente en cada rincón de Apalanchii.", rating: 5, relative_time_description: "Hace 2 meses" },
          { author_name: "Carlos V.", text: "La mejor experiencia wayuu. La calidez del personal hace que te sientas en casa.", rating: 5, relative_time_description: "Hace 3 semanas" }
        ]);
        setLoading(false);
        return;
      }

      const service = new g.maps.places.PlacesService(document.createElement('div'));
      const request = {
        query: 'Apalanchii Hospedaje y Restaurante, Cabo de la Vela, La Guajira',
        fields: ['place_id', 'reviews', 'rating', 'user_ratings_total']
      };

      service.textSearch(request, (results: any, status: any) => {
        if (status === g.maps.places.PlacesServiceStatus.OK && results && results[0]) {
          service.getDetails({ 
            placeId: results[0].place_id!,
            fields: ['reviews']
          }, (place: any, detailStatus: any) => {
            if (detailStatus === g.maps.places.PlacesServiceStatus.OK && place?.reviews) {
              const sorted = [...place.reviews].sort((a: any, b: any) => (b.rating || 0) - (a.rating || 0)).slice(0, 3);
              setReviews(sorted as GoogleReview[]);
            }
            setLoading(false);
          });
        } else {
          setLoading(false);
        }
      });
    };

    const timer = setTimeout(fetchReviews, 1000);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="view-transition">
      <SubpageHero 
        title={t.experiences.title} 
        subtitle={t.experiences.lead} 
        bgImage="https://static.wixstatic.com/media/be13c5_fa5793f6013847e1b92e0fcd39ca7bb5~mv2.png"
      />

      <section className="py-24 px-6 bg-white overflow-hidden">
        <div className="max-w-7xl mx-auto">
          {/* Galería Minimalista */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-32">
            {[
              { img: 'https://static.wixstatic.com/media/be13c5_fa5793f6013847e1b92e0fcd39ca7bb5~mv2.png', label: 'Punta Gallina' },
              { img: 'https://static.wixstatic.com/media/be13c5_f3a9de846dee4298bd09a2134f8c7a3e~mv2.jpg', label: 'Pilón de Azúcar' },
              { img: 'https://static.wixstatic.com/media/be13c5_be1ef171c3cf4733adc637f6a1e0dc03~mv2.png', label: 'Cueva del Diablo' },
              { img: 'https://static.wixstatic.com/media/be13c5_5ca5c936fc874ea1ba50c59d5ceaf470~mv2.png', label: 'Ojo de Agua' }
            ].map((item, i) => (
              <div key={i} className={`group relative h-[420px] rounded-3xl overflow-hidden bg-slate-50 animate-reveal stagger-${i+1}`}>
                <img loading="lazy" decoding="async" src={item.img} className="w-full h-full object-cover grayscale-[30%] group-hover:grayscale-0 transition-all duration-1000 group-hover:scale-105" alt={item.label} />
                <div className="absolute bottom-0 left-0 right-0 p-8 bg-gradient-to-t from-black/60 to-transparent">
                  <p className="text-white font-bold text-lg tracking-tight">{item.label}</p>
                </div>
              </div>
            ))}
          </div>

          {/* Sección de Reseñas Ultra Minimalista */}
          <div className="animate-reveal">
            <div className="text-center mb-24">
              <h2 className="text-2xl md:text-3xl font-black text-[#0b3b52] tracking-tighter uppercase mb-2">{t.experiences.reviewsTitle}</h2>
              <div className="w-10 h-0.5 bg-[#CBA76B] mx-auto"></div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-16 md:gap-8 max-w-6xl mx-auto">
              {loading ? (
                [1, 2, 3].map(i => (
                  <div key={i} className="h-48 bg-slate-50 rounded-2xl animate-pulse"></div>
                ))
              ) : reviews.length > 0 ? (
                reviews.map((rev, idx) => (
                  <article key={idx} className="flex flex-col items-center text-center group">
                    <div className="mb-6 relative">
                       {rev.profile_photo_url ? (
                        <img src={rev.profile_photo_url} alt={rev.author_name} className="w-12 h-12 rounded-full object-cover filter saturate-50" />
                      ) : (
                        <div className="w-12 h-12 rounded-full bg-slate-100 flex items-center justify-center font-bold text-[#0b3b52] text-sm">
                          {rev.author_name[0]}
                        </div>
                      )}
                    </div>

                    <div className="flex gap-0.5 mb-4 text-[#f5a623]">
                      {Array.from({ length: 5 }).map((_, i) => (
                        <svg key={i} className={`w-3 h-3 ${i < Math.round(rev.rating) ? 'fill-current' : 'fill-slate-200'}`} viewBox="0 0 24 24"><path d="M12 17.27 18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/></svg>
                      ))}
                    </div>

                    <blockquote className="text-slate-600 text-[13px] leading-relaxed mb-6 font-medium italic">
                      "{rev.text.length > 150 ? rev.text.substring(0, 150) + '...' : rev.text}"
                    </blockquote>

                    <div className="mt-auto">
                      <h4 className="text-[11px] font-black text-[#0b3b52] uppercase tracking-[0.2em] mb-1">{rev.author_name}</h4>
                      <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{rev.relative_time_description}</p>
                    </div>
                  </article>
                ))
              ) : (
                <div className="col-span-3 text-center py-12 text-slate-300 font-medium italic text-sm">Sin opiniones recientes.</div>
              )}
            </div>
          </div>
        </div>
      </section>
    </div>
  );
});

