export const AIAssistant: React.FC<Props> = ({ lang, t }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [showPrompt, setShowPrompt] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isThinking, setIsThinking] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const chatInstance = useMemo(() => createChatSession(lang), [lang]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isOpen) setShowPrompt(true);
    }, 5000);
    return () => clearTimeout(timer);
  }, [isOpen]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking]);

  const handleSend = async () => {
    if (!input.trim() || isThinking) return;

    const userMsg = input.trim();
    setInput('');
    setShowPrompt(false);
    setMessages(prev => [...prev, { text: userMsg, sender: 'user' }]);
    setIsThinking(true);

    try {
      const responseStream = await chatInstance.sendMessageStream({ message: userMsg });
      setMessages(prev => [...prev, { text: '', sender: 'bot', isStreaming: true }]);

      let fullText = '';
      let sources: string[] = [];

      for await (const chunk of responseStream) {
        const c = chunk as GenerateContentResponse;
        fullText += c.text || "";
        const chunkSources = c.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(ch => ch.web?.uri).filter(Boolean) as string[];
        if (chunkSources?.length) sources = Array.from(new Set([...sources, ...chunkSources]));

        setMessages(prev => {
          const updated = [...prev];
          const lastIndex = updated.length - 1;
          if (updated[lastIndex].sender === 'bot') {
            updated[lastIndex] = { ...updated[lastIndex], text: fullText, sources };
          }
          return updated;
        });
      }

      setMessages(prev => {
        const updated = [...prev];
        const lastIndex = updated.length - 1;
        if (updated[lastIndex].sender === 'bot') updated[lastIndex].isStreaming = false;
        return updated;
      });

    } catch (error) {
      setMessages(prev => [...prev, { text: lang === 'es' ? "¡Vaya! Parece que se enredó la red. ¿Intentamos de nuevo?" : "Oops! Looks like the net got tangled. Try again?", sender: 'bot' }]);
    } finally {
      setIsThinking(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100] font-sans pointer-events-none">
      {/* Globo de invitación de Ka'la */}
      {showPrompt && !isOpen && (
        <div className="absolute bottom-[80px] right-0 mb-3 w-56 bg-white p-4 rounded-3xl shadow-2xl border border-slate-100 animate-reveal pointer-events-auto origin-bottom-right">
          <div className="flex gap-3 items-start">
             <div className="flex-1">
               <p className="text-[11px] font-bold text-slate-800 leading-tight">
                 {t.assistant.invitation}
               </p>
               <p className="text-[9px] text-[#1f7a8c] font-black uppercase tracking-widest mt-1">Atentamente, Ka'la</p>
             </div>
          </div>
          <div className="absolute bottom-[-6px] right-8 w-3 h-3 bg-white border-r border-b border-slate-100 rotate-45"></div>
        </div>
      )}

      {/* Botón Flotante con Avatar de Ka'la */}
      <button
        onClick={() => { setIsOpen(!isOpen); setShowPrompt(false); }}
        className="ml-auto w-16 h-16 bg-[#0b3b52] rounded-full shadow-2xl hover:bg-[#1f7a8c] flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 pointer-events-auto group p-0.5 overflow-visible"
        aria-label="Hablar con Ka'la"
      >
        {isOpen ? (
          <div className="text-white">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </div>
        ) : (
          <KaLaAvatar size="md" />
        )}
      </button>

      {/* Ventana de Chat */}
      {isOpen && (
        <div className="absolute bottom-[84px] right-0 w-[320px] md:w-[400px] h-[550px] bg-white rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden border border-slate-100 animate-reveal pointer-events-auto mb-2 origin-bottom-right">
          {/* Header con Ka'la */}
          <div className="bg-gradient-to-r from-[#0b3b52] to-[#1f7a8c] p-6 text-white">
            <div className="flex items-center gap-4">
              <KaLaAvatar size="sm" animated={false} />
              <div>
                <h3 className="text-sm font-black uppercase tracking-[0.2em] leading-none mb-1">Ka'la</h3>
                <p className="text-[10px] font-bold text-white/60 uppercase tracking-widest">Guía Apalanchii</p>
              </div>
              <button onClick={() => setIsOpen(false)} className="ml-auto opacity-40 hover:opacity-100 transition-opacity">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
              </button>
            </div>
          </div>

          {/* Cuerpo del Chat */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-5 bg-[#f7f0e3]/30">
            {messages.length === 0 && (
              <div className="text-center py-12 px-6">
                <div className="mb-4 flex justify-center opacity-30">
                  <KaLaAvatar size="lg" animated={false} />
                </div>
                <p className="text-slate-400 text-xs leading-relaxed italic font-medium">{t.assistant.greeting}</p>
              </div>
            )}

            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-2xl text-[13px] leading-relaxed transition-all ${
                  msg.sender === 'user' 
                    ? 'bg-[#0b3b52] text-white rounded-tr-none shadow-lg' 
                    : 'bg-white text-slate-700 shadow-sm border border-slate-100 rounded-tl-none font-medium'
                }`}>
                  {msg.text || (msg.isStreaming && <span className="inline-block w-1.5 h-4 bg-[#1f7a8c] animate-pulse align-middle"></span>)}

                  {msg.sources && msg.sources.length > 0 && (
                    <div className="mt-3 pt-3 border-t border-slate-50">
                      <p className="text-[8px] font-black text-[#CBA76B] mb-2 uppercase tracking-widest">Sabiduría del Mar:</p>
                      <div className="flex flex-wrap gap-2">
                        {msg.sources.map((src, i) => (
                          <a key={i} href={src} target="_blank" rel="noopener noreferrer" className="px-2 py-1 bg-slate-50 rounded-md text-[9px] text-[#1f7a8c] font-bold hover:bg-[#1f7a8c] hover:text-white transition-all truncate max-w-[120px]">
                            {new URL(src).hostname}
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            ))}

            {isThinking && messages[messages.length-1]?.sender !== 'bot' && (
              <div className="flex justify-start">
                <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 rounded-tl-none">
                  <div className="flex gap-1.5 items-center">
                    <div className="w-1.5 h-1.5 bg-[#CBA76B] rounded-full animate-bounce"></div>
                    <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest ml-2">{t.assistant.thinking}</span>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-5 bg-white border-t border-slate-100">
            <div className="flex gap-2 items-center bg-slate-50 rounded-2xl px-4 py-1.5 focus-within:ring-2 focus-within:ring-[#1f7a8c]/20 transition-all">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={t.assistant.placeholder}
                className="flex-1 text-[13px] bg-transparent border-none py-3 outline-none text-slate-700 placeholder:text-slate-400 font-medium"
              />
              <button
                onClick={handleSend}
                disabled={isThinking || !input.trim()}
                className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${
                  input.trim() ? 'bg-[#1f7a8c] text-white shadow-lg' : 'bg-slate-200 text-slate-400'
                }`}
              >
                <svg className="w-4 h-4 transform rotate-45" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
              </button>
            </div>
            <p className="text-[8px] text-center text-slate-300 font-bold uppercase tracking-widest mt-4">Corazón Wayuu • Tecnología Gemini</p>
          </div>
        </div>
      )}
    </div>
  );
};

