                ))
              ) : reviews.length > 0 ? (
                reviews.map((rev, idx) => (
                  <article key={idx} className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col hover:shadow-xl transition-shadow duration-500">
