            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 max-w-6xl mx-auto">
              {loading ? (
                [1, 2, 3].map(i => (
                  <div key={i} className="h-64 bg-white rounded-[2.5rem] animate-pulse border border-slate-100 shadow-sm"></div>
                ))
              ) : (
                reviews.map((rev, idx) => (
                  <article key={idx} className="bg-white p-10 rounded-[2.5rem] shadow-[0_10px_40px_-15px_rgba(0,0,0,0.05)] border border-slate-100 flex flex-col transition-all duration-500 hover:shadow-2xl hover:-translate-y-2">
                    <div className="flex items-center gap-4 mb-8">
                      {rev.profile_photo_url ? (
