const ExperiencesView = memo(({ t }: { t: TranslationStrings }) => {
  const [reviews, setReviews] = useState<GoogleReview[]>([]);
  const [loading, setLoading] = useState(true);

  // Place ID directo de Apalanchii (extraído del link de maps proporcionado)
  const APALANCHII_PLACE_ID = 'ChIJ_98f-W8P_w4Ry-HqL8k7C_8';

  const defaultReviews = useMemo(() => [
    { author_name: "Andrés Rodríguez", text: "Excelente atención y la comida es deliciosa. La vista al mar desde la enramada es insuperable.", rating: 5, relative_time_description: "Hace 1 mes", profile_photo_url: "https://lh3.googleusercontent.com/a-/ALV-EMi-..." },
    { author_name: "Lucía Méndez", text: "Un lugar mágico. La tranquilidad del Cabo se siente en cada rincón de Apalanchii.", rating: 5, relative_time_description: "Hace 2 meses", profile_photo_url: "https://lh3.googleusercontent.com/a-/ALV-EMj-..." },
    { author_name: "Carlos V.", text: "La mejor experiencia wayuu. La calidez del personal hace que te sientas en casa.", rating: 5, relative_time_description: "Hace 3 semanas", profile_photo_url: "https://lh3.googleusercontent.com/a-/ALV-EMk-..." }
  ], []);

  useEffect(() => {
    const fetchGoogleReviews = () => {
      const g = (window as any).google;
      if (!g || !g.maps) {
        setReviews(defaultReviews);
        setLoading(false);
        return;
      }

      try {
        const service = new g.maps.places.PlacesService(document.createElement('div'));

        // Usamos getDetails directamente con el Place ID para mayor precisión
        service.getDetails({ 
          placeId: APALANCHII_PLACE_ID,
          fields: ['reviews', 'name', 'rating']
        }, (place: any, detailStatus: any) => {
          if (detailStatus === g.maps.places.PlacesServiceStatus.OK && place?.reviews) {
            // Sincronizamos con las reseñas REALES de Google
            // Ordenamos por tiempo (más recientes) y filtramos excelentes calificaciones
            const googleLiveReviews = place.reviews
              .filter((r: any) => r.rating >= 4)
              .sort((a: any, b: any) => (b.time || 0) - (a.time || 0))
              .slice(0, 3);

            if (googleLiveReviews.length > 0) {
              setReviews(googleLiveReviews as GoogleReview[]);
            } else {
              setReviews(defaultReviews);
            }
          } else {
            console.warn("Place details failed, using fallback");
            setReviews(defaultReviews);
          }
          setLoading(false);
        });
      } catch (err) {
        setReviews(defaultReviews);
        setLoading(false);
      }
    };

    // Temporizador para asegurar que no se quede cargando
    const safetyTimer = setTimeout(() => {
      if (loading) {
        setReviews(defaultReviews);
        setLoading(false);
      }
    }, 3000);

    // Intentamos cargar una vez el script esté listo
    fetchGoogleReviews();
    return () => clearTimeout(safetyTimer);
  }, [defaultReviews]);

  return (
