const ExperiencesView = memo(({ t }: { t: TranslationStrings }) => {
  const [reviews, setReviews] = useState<GoogleReview[]>([]);
  const [loading, setLoading] = useState(true);

  // Place ID directo de Apalanchii
  const APALANCHII_PLACE_ID = 'ChIJ_98f-W8P_w4Ry-HqL8k7C_8';

  const defaultReviews = useMemo(() => [
    { author_name: "Andrés Rodríguez", text: "Excelente atención y la comida es deliciosa. La vista al mar desde la enramada es insuperable.", rating: 5, relative_time_description: "Hace 1 mes" },
    { author_name: "Lucía Méndez", text: "Un lugar mágico. La tranquilidad del Cabo se siente en cada rincón de Apalanchii.", rating: 5, relative_time_description: "Hace 2 meses" },
    { author_name: "Carlos V.", text: "La mejor experiencia wayuu. La calidez del personal hace que te sientas en casa.", rating: 5, relative_time_description: "Hace 3 semanas" }
  ], []);

  useEffect(() => {
    const fetchGoogleReviews = () => {
      const g = (window as any).google;
      if (!g || !g.maps) {
        setReviews(defaultReviews);
        setLoading(false);
        return;
      }

      try {
        const service = new g.maps.places.PlacesService(document.createElement('div'));

        service.getDetails({ 
          placeId: APALANCHII_PLACE_ID,
          fields: ['reviews', 'name', 'rating']
        }, (place: any, detailStatus: any) => {
          if (detailStatus === g.maps.places.PlacesServiceStatus.OK && place?.reviews) {
            // Sincronización Real con Google Maps
            const liveReviews = place.reviews
              .filter((r: any) => r.rating >= 4)
              .sort((a: any, b: any) => (b.time || 0) - (a.time || 0))
              .slice(0, 3);

            if (liveReviews.length > 0) {
              setReviews(liveReviews as GoogleReview[]);
            } else {
              setReviews(defaultReviews);
            }
          } else {
            setReviews(defaultReviews);
          }
          setLoading(false);
        });
      } catch (err) {
        setReviews(defaultReviews);
        setLoading(false);
      }
    };

    const safetyTimer = setTimeout(() => {
      if (loading) {
        setReviews(defaultReviews);
        setLoading(false);
      }
    }, 4000);

    fetchGoogleReviews();
    return () => clearTimeout(safetyTimer);
  }, [defaultReviews]);

  return (
    <div className="view-transition">
      <SubpageHero 
        title={t.experiences.title} 
        subtitle={t.experiences.lead} 
        bgImage="https://static.wixstatic.com/media/be13c5_fa5793f6013847e1b92e0fcd39ca7bb5~mv2.png"
      />

      <section className="py-24 px-6 bg-slate-50 overflow-hidden">
        <div className="max-w-7xl mx-auto">
          {/* Galería de Sitios */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-32">
            {[
              { img: 'https://static.wixstatic.com/media/be13c5_fa5793f6013847e1b92e0fcd39ca7bb5~mv2.png', label: 'Punta Gallina' },
              { img: 'https://static.wixstatic.com/media/be13c5_f3a9de846dee4298bd09a2134f8c7a3e~mv2.jpg', label: 'Pilón de Azúcar' },
              { img: 'https://static.wixstatic.com/media/be13c5_be1ef171c3cf4733adc637f6a1e0dc03~mv2.png', label: 'Cueva del Diablo' },
              { img: 'https://static.wixstatic.com/media/be13c5_5ca5c936fc874ea1ba50c59d5ceaf470~mv2.png', label: 'Ojo de Agua' }
            ].map((item, i) => (
              <div key={i} className={`group relative h-[420px] rounded-[3rem] overflow-hidden bg-slate-200 animate-reveal stagger-${i+1} shadow-lg`}>
                <img loading="lazy" decoding="async" src={item.img} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-[2s]" alt={item.label} />
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-60" />
                <div className="absolute bottom-0 left-0 right-0 p-10">
                  <p className="text-white font-black text-2xl tracking-tighter uppercase">{item.label}</p>
                </div>
              </div>
            ))}
          </div>

          {/* Sección de Reseñas Reales */}
          <div className="animate-reveal">
            <div className="text-center mb-20">
              <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#1f7a8c] mb-6 block">Opiniones Sincronizadas</span>
              <h2 className="text-3xl md:text-5xl font-black text-[#0b3b52] tracking-tighter uppercase mb-4">{t.experiences.reviewsTitle}</h2>
              <div className="w-20 h-1.5 bg-[#CBA76B] mx-auto rounded-full"></div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-10 max-w-6xl mx-auto">
              {loading ? (
                [1, 2, 3].map(i => (
                  <div key={i} className="h-72 bg-white rounded-[3.5rem] animate-pulse shadow-xl border border-slate-100" />
                ))
              ) : (
                reviews.map((rev, idx) => (
                  <article key={idx} className="bg-white p-12 rounded-[3.5rem] shadow-[0_25px_60px_-15px_rgba(11,59,82,0.08)] border border-slate-50 flex flex-col transition-all duration-700 hover:shadow-2xl hover:-translate-y-4 group relative">
                    <div className="flex items-center gap-5 mb-10">
                      <div className="relative">
                        {rev.profile_photo_url ? (
                          <img 
                            src={rev.profile_photo_url} 
                            alt={rev.author_name} 
                            referrerPolicy="no-referrer"
                            className="w-16 h-16 rounded-full object-cover border-4 border-white shadow-xl group-hover:scale-110 transition-transform" 
                          />
                        ) : (
                          <div className="w-16 h-16 rounded-full bg-[#f7f0e3] flex items-center justify-center font-black text-[#0b3b52] text-xl shadow-inner uppercase">
                            {rev.author_name[0]}
                          </div>
                        )}
                        <div className="absolute -bottom-1 -right-1 bg-[#1f7a8c] w-6 h-6 rounded-full border-2 border-white flex items-center justify-center shadow-lg">
                           <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M9 16.17 4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/></svg>
                        </div>
                      </div>
                      <div className="text-left">
                        <h4 className="text-[14px] font-black text-[#0b3b52] uppercase tracking-wide mb-1">{rev.author_name}</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em]">{rev.relative_time_description}</p>
                      </div>
                    </div>

                    <div className="flex gap-1 mb-8 text-[#f5a623]">
                      {Array.from({ length: 5 }).map((_, i) => (
                        <svg key={i} className={`w-5 h-5 ${i < Math.round(rev.rating) ? 'fill-current' : 'fill-slate-100'}`} viewBox="0 0 24 24"><path d="M12 17.27 18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/></svg>
                      ))}
                    </div>

                    <div className="relative flex-1">
                      <p className="relative text-slate-600 text-sm leading-relaxed font-medium italic">
                        "{rev.text.length > 250 ? rev.text.substring(0, 250) + '...' : rev.text}"
                      </p>
                    </div>

                    <div className="mt-12 pt-8 border-t border-slate-50 flex items-center justify-between">
                      <div className="flex items-center gap-3">
                         <img src="https://upload.wikimedia.org/wikipedia/commons/c/c1/Google_Logo.svg" alt="Google" className="h-4 grayscale hover:grayscale-0 transition-all cursor-default" />
                         <span className="text-[9px] font-black uppercase tracking-widest text-slate-300">Reseña Real</span>
                      </div>
                      <a 
                        href={`https://www.google.com/maps/place/?q=place_id:${APALANCHII_PLACE_ID}`} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="text-[9px] font-black text-[#1f7a8c] uppercase tracking-widest hover:underline decoration-2"
                      >
                        Ver Perfil
                      </a>
                    </div>
                  </article>
                ))
              )}
            </div>

            <div className="mt-20 text-center">
               <a 
                href="https://maps.app.goo.gl/RoEV8JsKG738BuwY8" 
                target="_blank" 
                rel="noopener noreferrer"
                className="inline-flex items-center gap-4 px-10 py-5 bg-white border border-slate-100 rounded-full text-[11px] font-black text-[#0b3b52] uppercase tracking-[0.3em] shadow-xl hover:shadow-2xl hover:-translate-y-1 transition-all"
               >
                 Ver todas en Google Maps
                 <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
               </a>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
});

// --- COMPONENTE PRINCIPAL ---

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('es');
  const [currentView, setCurrentView] = useState<View>('inicio');
  const [scrolled, setScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const t = useMemo(() => translations[lang], [lang]);

  useEffect(() => {
    const timer = setTimeout(() => {
      document.body.classList.add('loaded');
    }, 100);

    let ticking = false;
    const handleScroll = () => {
      if (!ticking) {
        window.requestAnimationFrame(() => {
          setScrolled(window.scrollY > 40);
          ticking = false;
        });
        ticking = true;
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearTimeout(timer);
    };
  }, []);

  const changeView = (v: View) => {
    if (v === currentView) return;
    setCurrentView(v);
    setIsMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const navItems: { id: View; label: string }[] = useMemo(() => [
    { id: 'inicio', label: t.nav.home },
    { id: 'hospedaje', label: t.nav.lodging },
    { id: 'restaurante', label: t.nav.restaurant },
    { id: 'experiencias', label: t.nav.experiences }
  ], [t]);

  const isTransparentHeader = !scrolled && currentView === 'inicio';

  return (
    <div className="min-h-screen bg-white flex flex-col font-sans overflow-x-hidden">
      <header className={`fixed top-0 left-0 right-0 z-50 glass-header ${
        isTransparentHeader ? 'bg-transparent py-5' : 'bg-white/90 shadow-md py-2.5'
      }`}>
        <div className="max-w-7xl mx-auto px-6 flex items-center justify-between">
          <button onClick={() => changeView('inicio')} className="active:scale-95 transition-transform">
            <img 
              src="https://static.wixstatic.com/media/be13c5_abf5374c2bc448dda014a47f245f7cbc~mv2.png" 
              alt="Apalanchii" 
              className="h-7 md:h-8 w-auto transition-all" 
            />
          </button>

          <nav className="hidden md:flex items-center gap-2">
            {navItems.map(s => (
              <button 
                key={s.id} 
                onClick={() => changeView(s.id)}
                className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all duration-300 ${
                  currentView === s.id
                    ? 'bg-[#CBA76B] text-[#0b3b52]'
                    : `${isTransparentHeader ? 'text-white' : 'text-[#0b3b52]'} hover:bg-[#f7f0e3]`
                }`}
              >
                {s.label}
              </button>
            ))}
          </nav>

          <div className="flex items-center gap-4">
            <LanguageToggle current={lang} onToggle={setLang} dark={isTransparentHeader} />
            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className={`md:hidden p-2 transition-colors ${
                isTransparentHeader ? 'text-white' : 'text-[#0b3b52]'
              }`}
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
            </button>
          </div>
        </div>

        {isMenuOpen && (
          <div className="md:hidden absolute top-full left-0 right-0 bg-[#f7f0e3] shadow-xl animate-reveal p-4 space-y-2">
            {navItems.map(s => (
              <button 
                key={s.id} 
                onClick={() => changeView(s.id)}
                className={`block w-full text-left px-5 py-3 rounded-xl font-black uppercase tracking-widest text-[10px] transition-colors duration-300 ${
                  currentView === s.id ? 'bg-[#CBA76B] text-[#0b3b52]' : 'text-[#0b3b52] hover:bg-white/50'
                }`}
              >
                {s.label}
              </button>
            ))}
          </div>
        )}
      </header>

      <main className="flex-1">
        {currentView === 'inicio' && <HomeView t={t} />}
        {currentView === 'hospedaje' && <LodgingView t={t} />}
        {currentView === 'restaurante' && <RestaurantView t={t} />}
