        <div className="absolute -bottom-20 -left-20 w-40 h-40 bg-[#1f7a8c]/10 blur-[80px] rounded-full pointer-events-none"></div>

        <div className="relative flex flex-col gap-6">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-2xl bg-[#0b3b52] flex items-center justify-center text-[#CBA76B] shadow-inner flex-shrink-0">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
