import React, { useState, useRef, useEffect, useMemo } from 'react';
import { createChatSession } from '../services/geminiService.ts';
import { Language, TranslationStrings } from '../types.ts';
import { GenerateContentResponse } from "@google/genai";

interface Message {
  text: string;
  sender: 'user' | 'bot';
  sources?: string[];
  isStreaming?: boolean;
}

interface Props {
  lang: Language;
  t: TranslationStrings;
}

const KaLaAvatar = ({ size = "md", animated = true }: { size?: "sm" | "md" | "lg", animated?: boolean }) => {
  const dimensions = size === "sm" ? "w-8 h-8" : size === "md" ? "w-12 h-12" : "w-16 h-16";
  return (
    <div className={`${dimensions} relative flex items-center justify-center bg-gradient-to-br from-[#1f7a8c] to-[#0b3b52] rounded-full shadow-inner overflow-visible ${animated ? 'animate-bounce' : ''}`} style={{ animationDuration: '3s' }}>
      <svg className="absolute -top-3 w-[120%] h-auto drop-shadow-md" viewBox="0 0 100 40" fill="none">
        <path d="M10 30C10 30 25 10 50 10C75 10 90 30 90 30H10Z" fill="#CBA76B" />
        <rect x="15" y="25" width="70" height="5" fill="#a6854d" />
        <path d="M30 15L70 15" stroke="white" strokeWidth="1" strokeDasharray="2 2" />
      </svg>
      <div className="relative w-3/4 h-3/4 bg-[#e5c298] rounded-full mt-1 flex flex-col items-center justify-center border-b-2 border-[#0b3b5220]">
        <div className="flex gap-2 mb-1">
          <div className="w-1.5 h-1.5 bg-[#0b3b52] rounded-full animate-pulse"></div>
          <div className="w-1.5 h-1.5 bg-[#0b3b52] rounded-full animate-pulse"></div>
        </div>
        <div className="w-3 h-1.5 border-b-2 border-[#0b3b52] rounded-full"></div>
      </div>
    </div>
  );
};

export const AIAssistant: React.FC<Props> = ({ lang, t }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [showPrompt, setShowPrompt] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isThinking, setIsThinking] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);

  // Reiniciar chat cuando el idioma cambie
  const chatInstance = useMemo(() => {
    setMessages([]); // Limpiar mensajes al cambiar idioma
    return createChatSession(lang);
  }, [lang]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isOpen) setShowPrompt(true);
    }, 5000);
    return () => clearTimeout(timer);
  }, [isOpen]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking]);

  const handleSend = async () => {
    if (!input.trim() || isThinking) return;

    const userMsg = input.trim();
    setInput('');
    setShowPrompt(false);
    setMessages(prev => [...prev, { text: userMsg, sender: 'user' }]);
    setIsThinking(true);

    try {
      const responseStream = await chatInstance.sendMessageStream({ message: userMsg });
      setMessages(prev => [...prev, { text: '', sender: 'bot', isStreaming: true }]);

      let fullText = '';
      let sources: string[] = [];

      for await (const chunk of responseStream) {
        const c = chunk as GenerateContentResponse;
        fullText += c.text || "";
        const chunkSources = c.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(ch => ch.web?.uri).filter(Boolean) as string[];
        if (chunkSources?.length) sources = Array.from(new Set([...sources, ...chunkSources]));

        setMessages(prev => {
          const updated = [...prev];
          const lastIndex = updated.length - 1;
          if (updated[lastIndex].sender === 'bot') {
            updated[lastIndex] = { ...updated[lastIndex], text: fullText, sources };
          }
          return updated;
        });
      }

      setMessages(prev => {
        const updated = [...prev];
        const lastIndex = updated.length - 1;
        if (updated[lastIndex].sender === 'bot') updated[lastIndex].isStreaming = false;
        return updated;
      });

    } catch (error) {
      setMessages(prev => [...prev, { text: lang === 'es' ? "¡Vaya! Parece que se enredó la red. ¿Intentamos de nuevo?" : "Oops! Looks like the net got tangled. Try again?", sender: 'bot' }]);
    } finally {
      setIsThinking(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100] font-sans pointer-events-none">
      {showPrompt && !isOpen && (
        <div className="absolute bottom-[80px] right-0 mb-3 w-56 bg-white p-4 rounded-3xl shadow-2xl border border-slate-100 animate-reveal pointer-events-auto origin-bottom-right">
          <div className="flex gap-3 items-start">
             <div className="flex-1">
               <p className="text-[11px] font-bold text-slate-800 leading-tight">
                 {t.assistant.invitation}
               </p>
               <p className="text-[9px] text-[#1f7a8c] font-black uppercase tracking-widest mt-1">
                 {lang === 'es' ? 'Atentamente, Ka\'la' : 'Best regards, Ka\'la'}
               </p>
             </div>
          </div>
          <div className="absolute bottom-[-6px] right-8 w-3 h-3 bg-white border-r border-b border-slate-100 rotate-45"></div>
        </div>
      )}

      <button
        onClick={() => { setIsOpen(!isOpen); setShowPrompt(false); }}
        className="ml-auto w-16 h-16 bg-[#0b3b52] rounded-full shadow-2xl hover:bg-[#1f7a8c] flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 pointer-events-auto group p-0.5"
      >
        {isOpen ? (
          <div className="text-white">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </div>
        ) : (
          <KaLaAvatar size="md" />
        )}
      </button>

      {isOpen && (
        <div className="absolute bottom-[84px] right-0 w-[320px] md:w-[400px] h-[550px] bg-white rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden border border-slate-100 animate-reveal pointer-events-auto mb-2 origin-bottom-right">
          <div className="bg-gradient-to-r from-[#0b3b52] to-[#1f7a8c] p-6 text-white">
            <div className="flex items-center gap-4">
              <KaLaAvatar size="sm" animated={false} />
              <div>
                <h3 className="text-sm font-black uppercase tracking-[0.2em] leading-none mb-1">Ka'la</h3>
                <p className="text-[10px] font-bold text-white/60 uppercase tracking-widest">
                  {lang === 'es' ? 'Guía Apalanchii' : 'Apalanchii Guide'}
                </p>
              </div>
            </div>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-5 bg-[#f7f0e3]/30">
            {messages.length === 0 && (
              <div className="text-center py-12 px-6">
                <div className="mb-4 flex justify-center opacity-30">
                  <KaLaAvatar size="lg" animated={false} />
                </div>
                <p className="text-slate-400 text-xs leading-relaxed italic font-medium">{t.assistant.greeting}</p>
              </div>
            )}

            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-2xl text-[13px] leading-relaxed ${
                  msg.sender === 'user' ? 'bg-[#0b3b52] text-white shadow-lg' : 'bg-white text-slate-700 shadow-sm border border-slate-100 font-medium'
                }`}>
                  {msg.text || (msg.isStreaming && <span className="inline-block w-1.5 h-4 bg-[#1f7a8c] animate-pulse"></span>)}
                </div>
              </div>
            ))}

            {isThinking && messages[messages.length-1]?.sender !== 'bot' && (
              <div className="flex justify-start">
                <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
                  <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">{t.assistant.thinking}</span>
                </div>
              </div>
            )}
          </div>

          <div className="p-5 bg-white border-t border-slate-100">
            <div className="flex gap-2 items-center bg-slate-50 rounded-2xl px-4 py-1.5">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={t.assistant.placeholder}
                className="flex-1 text-[13px] bg-transparent border-none py-3 outline-none text-slate-700 font-medium"
              />
              <button
                onClick={handleSend}
                disabled={isThinking || !input.trim()}
                className={`w-10 h-10 rounded-xl flex items-center justify-center ${
                  input.trim() ? 'bg-[#1f7a8c] text-white' : 'bg-slate-200 text-slate-400'
                }`}
              >
                <svg className="w-4 h-4 transform rotate-45" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

