const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('es');
  const [currentView, setCurrentView] = useState<View>('inicio');
  const [scrolled, setScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const t = useMemo(() => translations[lang], [lang]);

  useEffect(() => {
    const timer = setTimeout(() => {
      document.body.classList.add('loaded');
    }, 100);

    const handleScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearTimeout(timer);
    };
  }, []);

  const changeView = (v: View) => {
    if (v === currentView) return;
    setCurrentView(v);
    setIsMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const navItems: { id: View; label: string }[] = useMemo(() => [
    { id: 'inicio', label: t.nav.home },
    { id: 'hospedaje', label: t.nav.lodging },
    { id: 'restaurante', label: t.nav.restaurant },
    { id: 'experiencias', label: t.nav.experiences }
  ], [t]);

  const isTransparentHeader = !scrolled && (currentView === 'inicio');

  return (
    <div className="min-h-screen bg-white flex flex-col font-sans overflow-x-hidden">
      <header className={`fixed top-0 left-0 right-0 z-50 glass-header ${
        isTransparentHeader ? 'bg-transparent py-5' : 'bg-white/90 shadow-md py-2.5'
      }`}>
        <div className="max-w-7xl mx-auto px-6 flex items-center justify-between">
          <button onClick={() => changeView('inicio')} className="active:scale-95 transition-transform">
            <img src="https://static.wixstatic.com/media/be13c5_abf5374c2bc448dda014a47f245f7cbc~mv2.png" alt="Apalanchii" className="h-7 md:h-8 w-auto" />
          </button>

          <nav className="hidden md:flex items-center gap-2">
            {navItems.map(s => (
              <button 
                key={s.id} 
                onClick={() => changeView(s.id)}
                className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all duration-300 ${
                  currentView === s.id ? 'bg-[#CBA76B] text-[#0b3b52]' : `${isTransparentHeader ? 'text-white' : 'text-[#0b3b52]'} hover:bg-[#f7f0e3]`
                }`}
              >
                {s.label}
              </button>
            ))}
          </nav>

          <div className="flex items-center gap-4">
            <LanguageToggle current={lang} onToggle={setLang} dark={isTransparentHeader} />
            <button onClick={() => setIsMenuOpen(!isMenuOpen)} className={`md:hidden p-2 ${isTransparentHeader ? 'text-white' : 'text-[#0b3b52]'}`}>
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1">
        {currentView === 'inicio' && <HomeView t={t} />}
        {currentView === 'hospedaje' && <LodgingView t={t} />}
        {currentView === 'restaurante' && <RestaurantView t={t} />}
        {currentView === 'experiencias' && <ExperiencesView t={t} />}
        {currentView === 'legal' && <LegalView t={t} />}
      </main>

      <footer className="relative mt-8 text-white">
        <div className="bg-gradient-to-br from-[#0b3b52] to-[#1f7a8c] px-6 py-12">
          <div className="max-w-7xl mx-auto text-center md:text-left grid grid-cols-1 md:grid-cols-3 gap-8 items-start">
            <div className="space-y-4">
              <img src="https://static.wixstatic.com/media/be13c5_abf5374c2bc448dda014a47f245f7cbc~mv2.png" alt="Apalanchii" className="h-8 mx-auto md:mx-0" />
              <p className="text-white/60 text-[9px] uppercase tracking-widest">{t.footer.address}</p>
              <button onClick={() => changeView('legal')} className="text-[8px] text-white/30 hover:text-white uppercase tracking-widest font-bold">Nosotros</button>
            </div>
            <div>
              <h4 className="text-white/40 font-black mb-4 uppercase text-[8px] tracking-widest">{t.footer.contact}</h4>
              <a href="https://wa.me/573126306637" target="_blank" className="text-[10px] font-bold text-white/80">+57 312 630 6637</a>
            </div>
            <div>
              <h4 className="text-white/40 font-black mb-4 uppercase text-[8px] tracking-widest">{t.footer.follow}</h4>
              <div className="flex justify-center md:justify-start gap-4">
                <a href="#" className="w-8 h-8 rounded bg-white/5 flex items-center justify-center hover:bg-[#CBA76B] transition-colors"><svg viewBox="0 0 24 24" className="w-4 h-4 fill-current"><path d="M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5Zm0 2a3 3 0 0 0-3 3v10a3 3 0 0 0 3 3h10a3 3 0 0 0 3-3V7a3 3 0 0 0-3-3H7Zm5 3.5a5.5 5.5 0 1 1 0 11 5.5 5.5 0 0 1 0-11Zm5.25-1.5a1.25 1.25 0 1 1 0 2.5 1.25 1.25 0 0 1 0-2.5Z"/></svg></a>
              </div>
            </div>
          </div>
          <div className="mt-12 text-center text-[7px] text-white/20 uppercase tracking-[0.4em]">© 2025 Apalanchii • {t.footer.rights}</div>
        </div>
      </footer>

      <CookieConsent t={t} />
    </div>
  );
};

