// --- COMPONENTES ATÓMICOS ---

const SubpageHero = memo(({ title, subtitle, bgImage }: { title: string, subtitle: string, bgImage: string }) => (
  <section className="h-[40vh] md:h-[50vh] relative flex items-center justify-center overflow-hidden bg-[#0b3b52]">
