            <p className="text-white/60 text-[9px] uppercase tracking-[0.2em]">{t.footer.address}</p>
          </div>
          <div className="text-[7px] text-white/20 uppercase tracking-[0.4em] font-black">
            © 2025 Apalanchii • {t.footer.rights}
          </div>
        </div>
      </footer>
    </div>
  );
};

