const GoogleReviews = memo(({ t }: { t: TranslationStrings }) => {
  const [reviews, setReviews] = useState<any[]>([]);
  const [placeData, setPlaceData] = useState<{rating: number; total: number} | null>(null);

  useEffect(() => {
    // Fix: Access google object via type casting since it's injected globally by script
    const google = (window as any).google;
    if (typeof window === 'undefined' || !google || !google.maps) return;

    const mapDiv = document.createElement('div');
    const service = new google.maps.places.PlacesService(mapDiv);

    const request = {
      query: 'Apalanchii Hospedaje y Restaurante Cabo de la Vela',
      fields: ['place_id']
    };

    service.findPlaceFromQuery(request, (results: any[], status: any) => {
      if (status === google.maps.places.PlacesServiceStatus.OK && results && results[0]) {
        service.getDetails({
          placeId: results[0].place_id,
          fields: ['reviews', 'rating', 'user_ratings_total']
        }, (place: any, detailStatus: any) => {
          if (detailStatus === google.maps.places.PlacesServiceStatus.OK && place) {
            setReviews(place.reviews || []);
            setPlaceData({ rating: place.rating, total: place.user_ratings_total });
          }
        });
      }
    });
  }, []);

  if (reviews.length === 0) return null;

  return (
    <section className="py-24 px-6 bg-white relative overflow-hidden">
      <div className="absolute top-0 right-0 w-64 h-64 bg-[#f7f0e3] rounded-full blur-[80px] opacity-60 pointer-events-none"></div>
      <div className="max-w-7xl mx-auto relative z-10">
        <div className="text-center mb-16 animate-reveal">
          <span className="text-[#1f7a8c] font-bold text-[10px] tracking-[0.2em] uppercase mb-3 block">Prueba Social</span>
          <h2 className="text-3xl md:text-4xl font-black text-[#0b3b52] uppercase tracking-tight mb-4">{t.experiences.reviewsTitle}</h2>

          {placeData && (
            <div className="flex flex-col items-center gap-2 mt-4">
              <div className="flex items-center gap-3">
                <span className="text-4xl font-black text-[#0b3b52]">{placeData.rating}</span>
                <div className="flex text-lg gap-1">
                  {[...Array(5)].map((_, i) => (
                    <span key={i} className={i < Math.round(placeData.rating) ? "text-[#CBA76B]" : "text-slate-200"}>★</span>
                  ))}
