const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('es');
  const [currentView, setCurrentView] = useState<View>('inicio');
  const [scrolled, setScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const t = useMemo(() => translations[lang], [lang]);

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 40) setScrolled(true);
      else setScrolled(false);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });

    // Al finalizar la carga inicial, ocultamos el loader
    const timer = setTimeout(() => document.body.classList.add('loaded'), 50);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearTimeout(timer);
    };
  }, []);

  const changeView = (v: View) => {
    setCurrentView(v);
    setIsMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'instant' });
  };

  const navItems: { id: View; label: string }[] = useMemo(() => [
    { id: 'inicio', label: t.nav.home },
    { id: 'hospedaje', label: t.nav.lodging },
    { id: 'restaurante', label: t.nav.restaurant },
    { id: 'experiencias', label: t.nav.experiences }
  ], [t]);

  const isTransparentHeader = !scrolled && (currentView === 'inicio');

  return (
    <div className="min-h-screen bg-white flex flex-col font-sans overflow-x-hidden">
      <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        isTransparentHeader ? 'bg-transparent py-5' : 'bg-white/95 backdrop-blur-md shadow-sm py-3'
      }`}>
        <div className="max-w-7xl mx-auto px-6 flex items-center justify-between">
          <button onClick={() => changeView('inicio')} className="transition-transform active:scale-95">
            <img 
              src="https://static.wixstatic.com/media/be13c5_abf5374c2bc448dda014a47f245f7cbc~mv2.png" 
              alt="Apalanchii Logo" 
              width="120"
              height="32"
              className="h-8 w-auto" 
            />
          </button>

          <nav className="hidden md:flex items-center gap-2">
            {navItems.map(s => (
              <button 
                key={s.id} 
                onClick={() => changeView(s.id)}
                className={`px-4 py-2 rounded-full text-[10px] font-bold uppercase tracking-[0.2em] transition-all ${
                  currentView === s.id
                    ? 'bg-[#CBA76B] text-[#0b3b52]'
                    : `${isTransparentHeader ? 'text-white' : 'text-[#0b3b52]'} hover:bg-slate-100/10`
                }`}
              >
                {s.label}
              </button>
            ))}
          </nav>

          <div className="flex items-center gap-4">
            <LanguageToggle current={lang} onToggle={setLang} dark={isTransparentHeader} />
            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className={`md:hidden p-2 ${isTransparentHeader ? 'text-white' : 'text-[#0b3b52]'}`}
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg>
            </button>
          </div>
        </div>

        {isMenuOpen && (
          <div className="md:hidden absolute top-full left-0 right-0 bg-white shadow-2xl p-6 space-y-3 animate-reveal">
            {navItems.map(s => (
              <button 
                key={s.id} 
                onClick={() => changeView(s.id)}
                className="block w-full text-left px-5 py-4 rounded-xl font-black uppercase text-[11px] text-[#0b3b52] hover:bg-slate-50"
              >
                {s.label}
              </button>
            ))}
          </div>
        )}
      </header>

      <main className="flex-1">
        {currentView === 'inicio' && <HomeView t={t} />}
        {currentView === 'hospedaje' && <LodgingView t={t} />}
        {currentView === 'restaurante' && <RestaurantView t={t} />}
        {currentView === 'experiencias' && <ExperiencesView t={t} />}
        {currentView === 'legal' && <div className="pt-32 px-6 text-center h-[50vh]">{/* Contenido Nosotros */}</div>}
      </main>

      <footer className="bg-[#0b3b52] py-16 px-6 text-white/40">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <img 
            src="https://static.wixstatic.com/media/be13c5_abf5374c2bc448dda014a47f245f7cbc~mv2.png" 
            alt="Apalanchii" 
            width="100"
            height="28"
            loading="lazy"
            className="h-7 w-auto opacity-50 grayscale" 
          />
          <p className="text-[10px] uppercase tracking-widest font-bold">© 2025 Apalanchii — {t.footer.rights}</p>
        </div>
      </footer>
    </div>
  );
};

