                    className="w-12 h-12 rounded-full border border-slate-100 object-cover" 
                  />
                  <div className="flex-1 min-w-0">
                    <h4 className="font-bold text-[#0b3b52] text-sm truncate">{review.author_name}</h4>
                    <div className="flex text-[#CBA76B] text-[10px] gap-0.5">
                      {[...Array(5)].map((_, stars) => (
                         <span key={stars}>{stars < review.rating ? '★' : '☆'}</span>
                      ))}
                    </div>
                  </div>
                </div>
                <p className="text-slate-600 text-[13px] leading-relaxed font-light italic flex-1">"{review.text}"</p>
                <div className="mt-6 pt-4 border-t border-slate-50 flex justify-end">
                   <span className="text-[9px] text-slate-300 font-bold uppercase tracking-widest">{review.relative_time_description}</span>
                </div>
              </div>
            ))
          ) : (
            [1, 2, 3].map((n) => (
              <div key={n} className="h-64 bg-slate-50 rounded-[2.5rem] animate-pulse"></div>
            ))
          )}
        </div>
      </div>
    </section>
  );
});

